{"command": "python3 -c "
from PIL import Image, ImageFilter
import numpy as np
im=Image.open('radiograph.jpg').convert('L')
W,H=im.size
s=np.asarray(im.filter(ImageFilter.GaussianBlur(6))).astype(np.float32)
bg=np.asarray(im.filter(ImageFilter.GaussianBlur(40))).astype(np.float32)
dark=bg-s
for name,y0,y1,x0,x1 in [('upperR',0.30,0.40,0.16,0.40),('upperL',0.30,0.40,0.55,0.80),('upant',0.28,0.38,0.36,0.62),('lowant',0.60,0.74,0.40,0.58)]:
  B=dark[int(y0*H):int(y1*H), int(x0*W):int(x1*W)]
  bh,bw=B.shape; k=9; cand=[]
  for i in range(0,bh-k,k):
    for j in range(0,bw-k,k):
      blk=B[i:i+k,j:j+k]; idx=np.unravel_index(np.argmax(blk),blk.shape)
      cand.append((blk[idx], i+idx[0], j+idx[1]))
  cand.sort(reverse=True); sel=[]
  for v,i,j in cand:
    if v<9: break
    if all((abs(i-a)>=22 or abs(j-b)>=22) for _,a,b in sel): sel.append((v,i,j))
    if len(sel)>=10: break
  print(name)
  for v,i,j in sel: print('  x=%.3f y=%.3f dark=%.1f'%((j+x0*W)/W,(i+y0*H)/H,v))
""}
